/**
 * Idol motion pass: the rigged Idol runner plays text-to-motion clips (fal.ai hunyuan-motion, generated by
 * tools/idol/motion.mjs from tools/idol/motion-specs/serpentine-sky-run.json into the app's motion.generated.ts) through
 * the shared humanoid driver (apps/showcase-port-shared/idol). Render layer only: the simulation never reads it.
 *
 * State -> clip:
 *   - run:      "Run" loop; clip time follows the distance-driven run phase (presentation.ts `advanceRunPhase`), so the
 *               legs turn over with the road distance covered, never with wall time. At the game's 32-48 m/s the
 *               stride cannot cover the ground (a 1.9 m body), so the cadence is the game's existing one.
 *   - stand:    "Idle" loop at real frame time (menu, finish).
 *   - jump:     "Jump" synced to the sim's ballistic jump (take-off -> apex -> landing from y / vy / GRAVITY).
 *   - slide:    "Slide" with its low point on the sim slide's 40% mark.
 *   - lane hop: "DodgeLeft" (mirrored for a right hop) while the lane change is quick.
 *   - stumble:  "Stumble" over the sim's 0.75 s stumble.
 *   - flight / dive / fall: the game's own code pose (poseHero), converted to the canonical humanoid frame.
 * Every change of source cross-fades (motion.ts). Overlays kept on top of the clips: the body roll into bends and lane
 * changes (`lean`), and the aura surge's raised, splayed arms.
 */
import {
  createHumanoidAnimator,
  createHumanoidDriver,
  humanoidAirTime as airTime,
  humanoidClipGroundSpeed,
  humanoidEventTime as eventTime,
  humanoidLocomotionTime,
  quatAxisAngle,
  quatInv,
  quatMul,
  sampleHumanoidClip,
  type HumanoidAnimationPose,
  type HumanoidAnimator as MotionAnimator,
  type HumanoidDriver,
  type HumanoidMotionRequest as MotionRequest,
  type HumanoidPoseInput,
  type HumanoidRole,
  type IdolSkeleton,
  type Quat
} from "@aura3d/engine/animation";
import { MOTION_CLIPS, type MotionClipName } from "../../../apps/showcase-serpentine-sky-run-port/src/motion.generated";
import type { HeroPartPose } from "../hero";
import { GRAVITY } from "../sim";
import { HERO_HIP_Y, quatFromM3 } from "./idolRunner";

/** Seconds the sim's slide and stumble last (sim.ts `slide`, stumble onset). */
export const SLIDE_TIME = 0.55;
export const STUMBLE_TIME = 0.75;
/** Lane speed (m/s) above which the runner reads as hopping across lanes. */
export const DODGE_LANE_SPEED = 4;
/** Run phase per stride cycle (poseHero: one cycle = 2 pi = a left and a right step). */
const CYCLE = Math.PI * 2;

export interface RunnerMotionState {
  /** Real frame time (s). */
  readonly dt: number;
  /** Distance-driven run phase (rad), `advanceRunPhase`. */
  readonly phase: number;
  /** The runner covered road this frame. */
  readonly moving: boolean;
  readonly grounded: boolean;
  /** Height above the road (m) and vertical speed (m/s) of the sim jump. */
  readonly y: number;
  readonly vy: number;
  /** Seconds of slide left (sim `S.sliding`). */
  readonly sliding: number;
  readonly stumble: number;
  /** Lateral speed (m/s, + = to the runner's right). */
  readonly laneVel: number;
  /** Flight, dive and fall keep the code pose. */
  readonly flying: boolean;
  readonly diving: boolean;
  /** Roll into the bend / lane change (rad, poseHero `lean`). */
  readonly lean: number;
  /** Aura surge 0..1 (arms lift and splay). */
  readonly surge: number;
  /** poseHero's segment frames for this frame (code pose source). */
  readonly parts: Readonly<Record<string, HeroPartPose>>;
}

const HALF_TURN_Y: Quat = [0, 1, 0, 0];
/** Runner frame (x right, -z forward) -> canonical humanoid frame (+z forward, left = +x). */
const toCanonical = (q: Quat): Quat => quatMul(quatMul(HALF_TURN_Y, q), HALF_TURN_Y);
const local = (parent: Quat, child: Quat): Quat => quatMul(quatInv(parent), child);

/** poseHero's segment frames as a canonical humanoid pose (local rotations; rest = limbs hanging, facing +Z). */
export function heroPartsToHumanoid(parts: Readonly<Record<string, HeroPartPose>>): HumanoidPoseInput {
  const G = (id: string): Quat => toCanonical(quatFromM3(parts[id]!.m) as unknown as Quat);
  const hips = G("pelvis"), torso = G("torso"), head = G("head");
  const uL = G("upperL"), fL = G("foreL"), uR = G("upperR"), fR = G("foreR");
  const tL = G("thighL"), sL = G("shinL"), tR = G("thighR"), sR = G("shinR");
  const p = parts.pelvis!.p;
  return {
    rotations: {
      hips,
      spine: local(hips, torso),
      head: local(torso, head),
      leftUpperArm: local(torso, uL), leftLowerArm: local(uL, fL),
      rightUpperArm: local(torso, uR), rightLowerArm: local(uR, fR),
      leftUpperLeg: local(hips, tL), leftLowerLeg: local(tL, sL),
      rightUpperLeg: local(hips, tR), rightLowerLeg: local(tR, sR)
    },
    hipsOffset: [-p[0] / HERO_HIP_Y, (p[1] - HERO_HIP_Y) / HERO_HIP_Y, -p[2] / HERO_HIP_Y]
  };
}

/** Clip loops of the Run clip per stride cycle: counted once from the clip's left-foot touchdowns. */
function runCyclesPerLoop(driver: HumanoidDriver): number {
  const clip = MOTION_CLIPS.Run;
  const foot = driver.map.roles.leftFoot!;
  const n = 90, ys: number[] = [];
  for (let k = 0; k < n; k++) {
    const t = (k / n) * clip.duration;
    ys.push(driver.modelPositions(sampleRun(t))[foot]![1]);
  }
  const lo = Math.min(...ys), hi = Math.max(...ys), mid = (lo + hi) / 2;
  let rises = 0;
  for (let k = 0; k < n; k++) if (ys[k]! < mid && ys[(k + 1) % n]! >= mid) rises++;
  return Math.max(1, rises);
}
const sampleRun = (t: number) => sampleHumanoidClip(MOTION_CLIPS.Run, t, { loop: true });

/** Jump clip take-off (s): the deepest hip dip before the apex (the clip's own crouch-and-spring). */
export const jumpTakeoff = (() => {
  let cached: number | null = null;
  return (): number => {
    if (cached !== null) return cached;
    const clip = MOTION_CLIPS.Jump;
    const apex = Number(clip.meta?.apexTime ?? clip.duration / 2);
    let best = 0, low = Infinity;
    for (let t = 0; t < apex; t += 1 / 60) {
      const y = sampleHumanoidClip(clip, t, { loop: false }).hipsOffset?.[1] ?? 0;
      if (y < low) { low = y; best = t; }
    }
    cached = Math.min(best, apex - 0.1);
    return cached;
  };
})();

/** The dodge clip's own direction (canonical frame: left = +X), from its generated travel. */
const DODGE_GOES_LEFT = Number(MOTION_CLIPS.DodgeLeft.meta?.travelX ?? 1) > 0;

export interface RunnerMotion {
  readonly driver: HumanoidDriver;
  readonly animator: MotionAnimator<MotionClipName>;
  /** Source playing now (clip name, "~m" when mirrored, "pose:code"). */
  readonly current: string;
  /** Clip or code pose for this frame (canonical frame, overlays applied). */
  input(state: RunnerMotionState): HumanoidPoseInput;
  /** Object-form bone pose for `applyRetargetedPose` / `setAnimationPose`. */
  pose(state: RunnerMotionState, driver?: HumanoidDriver): HumanoidAnimationPose;
}

/** The game state's motion request (exported for tests). */
export function runnerMotionRequest(s: RunnerMotionState, cyclesPerLoop: number, hipHeight = HERO_HIP_Y): MotionRequest<MotionClipName> {
  if (s.flying || s.diving) return { pose: heroPartsToHumanoid(s.parts), key: "code", fade: 0.25 };
  if (s.stumble > 0.05) {
    const u = Math.max(0, Math.min(1, (STUMBLE_TIME - s.stumble) / STUMBLE_TIME));
    return { clip: "Stumble", time: u * MOTION_CLIPS.Stumble.duration * 0.85, loop: false, fade: 0.1 };
  }
  if (s.sliding > 0) {
    const u = 1 - s.sliding / SLIDE_TIME;
    return { clip: "Slide", time: eventTime(MOTION_CLIPS.Slide, u, 0.4, "lowTime"), loop: false, fade: 0.1 };
  }
  if (!s.grounded) {
    return { clip: "Jump", time: airTime(MOTION_CLIPS.Jump, Math.max(0, s.y), s.vy, -GRAVITY, jumpTakeoff()), loop: false, fade: 0.08 };
  }
  if (!s.moving) return { clip: "Idle", rate: 1, fade: 0.3 };
  if (Math.abs(s.laneVel) > DODGE_LANE_SPEED) return { clip: "DodgeLeft", mirror: (s.laneVel < 0) !== DODGE_GOES_LEFT, rate: 1.4, loop: false, fade: 0.12 };
  const clip = MOTION_CLIPS.Run;
  const speed = humanoidClipGroundSpeed(clip, hipHeight);
  const metres = (s.phase / CYCLE / cyclesPerLoop) * speed * clip.duration;
  const time = speed > 0 ? humanoidLocomotionTime(clip, metres, hipHeight) : ((s.phase / CYCLE / cyclesPerLoop) % 1) * clip.duration;
  return { clip: "Run", time, fade: 0.15 };
}

const ROLL_AXIS: readonly [number, number, number] = [0, 0, 1];

/** Body roll into the bend (whole body about the forward axis) and the surge's lifted arms, on top of any source. */
export function applyRunnerOverlays(input: HumanoidPoseInput, lean: number, surge: number): HumanoidPoseInput {
  const r = input.rotations;
  const hips = r.hips ?? ([0, 0, 0, 1] as Quat);
  const rotations: Partial<Record<HumanoidRole, Quat>> = { ...r, hips: quatMul(quatAxisAngle(ROLL_AXIS, lean), hips) };
  if (surge > 1e-3) {
    // arms lift sideways (away from the body) as the aura flares: left arm about -Z, right about +Z in the chest frame
    rotations.leftUpperArm = quatMul(quatAxisAngle([0, 0, 1], 0.5 * surge), r.leftUpperArm ?? [0, 0, 0, 1]);
    rotations.rightUpperArm = quatMul(quatAxisAngle([0, 0, 1], -0.5 * surge), r.rightUpperArm ?? [0, 0, 0, 1]);
  }
  return { ...input, rotations };
}

export function createRunnerMotion(skeleton: IdolSkeleton): RunnerMotion {
  const driver = createHumanoidDriver(skeleton);
  const animator = createHumanoidAnimator(MOTION_CLIPS);
  const cycles = runCyclesPerLoop(driver);
  const input = (s: RunnerMotionState) => {
    const base = animator.update(s.dt, runnerMotionRequest(s, cycles, driver.map.hipHeight));
    // the code pose already carries poseHero's lean (and surge splay); clips get them as overlays
    return animator.current === "pose:code" ? base : applyRunnerOverlays(base, s.lean, s.surge);
  };
  return {
    driver,
    animator,
    get current() { return animator.current; },
    input,
    pose: (s, d = driver) => d.pose(input(s))
  };
}
